const rows = $input.all().map(function(item) {
  return item.json;
});

function escapeHtml(value) {
  if (value === null || value === undefined) return "";
  return String(value)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;");
}

function number(value) {
  if (value === null || value === undefined || value === "") return "N/A";
  const num = Number(value);
  if (Number.isNaN(num)) return escapeHtml(value);
  return num.toLocaleString("en-US", { maximumFractionDigits: 0 });
}

function money(value) {
  if (value === null || value === undefined || value === "") return "N/A";
  const num = Number(value);
  if (Number.isNaN(num)) return escapeHtml(value);
  return "$" + num.toLocaleString("en-US", { maximumFractionDigits: 0 });
}

function percent(value) {
  if (value === null || value === undefined || value === "") return "N/A";
  const num = Number(value);
  if (Number.isNaN(num)) return escapeHtml(value);
  return (num * 100).toFixed(1) + "%";
}

function metric(label, value) {
  return `
    <div class="metric">
      <div class="metric-label">${escapeHtml(label)}</div>
      <div class="metric-value">${value}</div>
    </div>
  `;
}

function paragraph(row) {
  return `
    <section class="narrative-block">
      <h2>${escapeHtml(row.title)}</h2>
      <p>${escapeHtml(row.narrative)}</p>
      <p><strong>Recommended action:</strong> ${escapeHtml(row.recommended_action)}</p>
    </section>
  `;
}

function skuCard(row) {
  return `
    <article class="sku-card">
      <h3>${escapeHtml(row.title)}</h3>
      <p>${escapeHtml(row.narrative)}</p>
      <div class="sku-metrics">
        ${metric("Visits L6M", number(row.visits_l6m))}
        ${metric("CVR L6M", percent(row.cvr_l6m))}
        ${metric("GRS L6M", money(row.grs_l6m))}
        ${metric("5+ Reviews", percent(row.five_plus_review_coverage))}
        ${metric("Tag Coverage", percent(row.recommended_tag_coverage))}
        ${metric("Availability", percent(row.current_availability))}
      </div>
      <p class="flags"><strong>Flags:</strong> ${escapeHtml(row.blocker_flags || "No major readiness flag")}</p>
      <p><strong>Action:</strong> ${escapeHtml(row.recommended_action)}</p>
    </article>
  `;
}

const summary = rows.find(function(row) { return row.section === "executive_summary"; });
const levers = rows.filter(function(row) { return row.section === "growth_lever"; });
const skus = rows.filter(function(row) { return row.section === "sku_priority"; });

const summaryMetrics = summary ? `
  <div class="metrics-grid">
    ${metric("Total SKUs", number(summary.total_skus))}
    ${metric("Live SKUs", number(summary.live_skus))}
    ${metric("Visits L6M", number(summary.visits_l6m))}
    ${metric("CVR L6M", percent(summary.cvr_l6m))}
    ${metric("GRS L6M", money(summary.grs_l6m))}
    ${metric("Sponsored Product Spend L6M", money(summary.sponsored_product_spend_l6m))}
    ${metric("Avg 5+ Review Coverage", percent(summary.five_plus_review_coverage))}
    ${metric("Avg Tag Coverage", percent(summary.recommended_tag_coverage))}
    ${metric("Avg Availability", percent(summary.current_availability))}
    ${metric("Avg MRPI", percent(summary.current_mrpi))}
    ${metric("Avg WSI", percent(summary.current_wsi))}
  </div>
` : "";

const htmlBody = `
<!DOCTYPE html>
<html>
<head>
  <style>
    body {
      font-family: Arial, sans-serif;
      color: #222;
      line-height: 1.55;
      margin: 0;
      padding: 0;
      background: #f7f8fa;
    }

    .container {
      max-width: 1120px;
      margin: 0 auto;
      background: #fff;
      padding: 28px;
    }

    h1 {
      color: #17365d;
      margin-bottom: 6px;
    }

    .subtitle {
      color: #555;
      margin-top: 0;
      margin-bottom: 24px;
    }

    h2 {
      color: #1f4e79;
      border-bottom: 2px solid #d8e6f3;
      padding-bottom: 6px;
      margin-top: 30px;
    }

    h3 {
      color: #17365d;
      margin-bottom: 8px;
    }

    .executive {
      background: #eef5fb;
      border-left: 5px solid #1f4e79;
      padding: 16px 18px;
      margin-bottom: 22px;
    }

    .metrics-grid, .sku-metrics {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
      gap: 10px;
      margin: 14px 0;
    }

    .metric {
      border: 1px solid #d9e2ec;
      border-radius: 8px;
      padding: 10px;
      background: #fbfdff;
    }

    .metric-label {
      font-size: 11px;
      color: #66788a;
      text-transform: uppercase;
      letter-spacing: 0.04em;
    }

    .metric-value {
      font-size: 18px;
      font-weight: bold;
      color: #17365d;
      margin-top: 4px;
    }

    .narrative-block {
      margin-bottom: 18px;
    }

    .sku-card {
      border: 1px solid #ddd;
      border-radius: 10px;
      padding: 16px;
      margin-bottom: 14px;
      background: #fff;
      box-shadow: 0 1px 2px rgba(0, 0, 0, 0.04);
    }

    .flags {
      background: #fff8db;
      border-left: 4px solid #e2b93b;
      padding: 8px 10px;
    }
  </style>
</head>
<body>
  <div class="container">
    <h1>Elegance Linen Supplier Deep Dive</h1>
    <p class="subtitle">Supplier: Elegance Linen | SuID: 22695 | Focus: granular Wayfair scale plan across traffic, conversion, catalog readiness, pricing, availability, and PDP merchandising.</p>

    ${summary ? `
      <section class="executive">
        <h2>${escapeHtml(summary.title)}</h2>
        <p>${escapeHtml(summary.narrative)}</p>
        <p><strong>Recommended action:</strong> ${escapeHtml(summary.recommended_action)}</p>
      </section>
      ${summaryMetrics}
    ` : '<p><em>No supplier summary returned.</em></p>'}

    <section>
      <h2>What can move the needle</h2>
      ${levers.map(paragraph).join("\n")}
    </section>

    <section>
      <h2>SKU-level priorities</h2>
      <p>These are the SKUs I would use to structure the supplier conversation. The goal is to separate SKUs that are ready for funded traffic from SKUs that need catalog, trust, pricing, or availability work first.</p>
      ${skus.length ? skus.map(skuCard).join("\n") : '<p><em>No SKU priority rows returned.</em></p>'}
    </section>
  </div>
</body>
</html>
`;

return [{ json: { htmlBody } }];
